import{_ as d,o as r,c as a,a5 as e}from"./chunks/framework.B5tqjWbr.js";const c=JSON.parse('{"title":"🔗 交叉引用：新增模块映射","description":"","frontmatter":{"date":"2026-06-06T00:00:00.000Z","section":"电机控制","chapter":"cross-reference","chapterTitle":"交叉索引","chapterOrder":10,"category":"交叉索引","source":"motor","visibility":"public","title":"🔗 交叉引用：新增模块映射","tags":["motor-control"],"status":"learning","summary":"> 来源：[交叉引用映射表](./cross-reference-map.md)","navGroup":"入门与索引","navGroupOrder":10},"headers":[],"relativePath":"content/motor/cross-reference/xref-new-modules.md","filePath":"content/motor/cross-reference/xref-new-modules.md","lastUpdated":1783096495000}'),h={name:"content/motor/cross-reference/xref-new-modules.md"};function l(o,t,i,s,n,m){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="🔗-交叉引用-新增模块映射" tabindex="-1">🔗 交叉引用：新增模块映射 <a class="header-anchor" href="#🔗-交叉引用-新增模块映射" aria-label="Permalink to &quot;🔗 交叉引用：新增模块映射&quot;">​</a></h1><blockquote><p>来源：<a href="./cross-reference-map.html">交叉引用映射表</a></p></blockquote><hr><h2 id="hw-02b-电流采样拓扑-→-算法关联" tabindex="-1">HW-02B 电流采样拓扑 → 算法关联 <a class="header-anchor" href="#hw-02b-电流采样拓扑-→-算法关联" aria-label="Permalink to &quot;HW-02B 电流采样拓扑 → 算法关联&quot;">​</a></h2><div class="kb-table-scroll"><table><thead><tr><th>硬件知识点</th><th>影响的算法模块</th><th>影响机制</th><th>引用链接</th></tr></thead><tbody><tr><td>单电阻采样盲区</td><td>ALG-02 电流采样时序</td><td>SVPWM移相时刻受扇区和占空比约束</td><td><a href="./../algorithm/ALG-02-Current-Sampling-Timing.html">ALG-02</a></td></tr><tr><td>低侧采样PWM约束</td><td>ALG-05 有感FOC</td><td>占空比&gt;95%时采样窗口不足→电流环性能下降</td><td><a href="./../algorithm/ALG-05-Sensored-FOC.html">ALG-05</a></td></tr><tr><td>放大倍数与ADC精度</td><td>ADV-HW-01 PWM深度</td><td>增益选择影响信噪比→影响电流环带宽上限</td><td><a href="./../advanced/hardware-algorithm-bridge/ADV-HW-01-PWM-Current-Sampling.html">ADV-HW-01</a></td></tr></tbody></table></div><h3 id="alg-17-v-f-→-硬件-算法关联" tabindex="-1">ALG-17 V/F → 硬件/算法关联 <a class="header-anchor" href="#alg-17-v-f-→-硬件-算法关联" aria-label="Permalink to &quot;ALG-17 V/F → 硬件/算法关联&quot;">​</a></h3><div class="kb-table-scroll"><table><thead><tr><th>算法知识点</th><th>依赖的硬件/算法模块</th><th>关联机制</th><th>引用链接</th></tr></thead><tbody><tr><td>V/f恒压频比</td><td>ALG-01 FOC理论</td><td>V/F是FOC的简化版，不进行dq解耦</td><td><a href="./../algorithm/ALG-01-FOC-Theory.html">ALG-01</a></td></tr><tr><td>弱磁区运行</td><td>ALG-11 MTPA弱磁</td><td>V/F弱磁是自然进入（电压饱和），FOC弱磁是主动控制</td><td><a href="./../algorithm/ALG-11-MTPA-Flux-Weakening.html">ALG-11</a></td></tr><tr><td>V/F→FOC切换</td><td>ALG-05 有感FOC</td><td>开环V/F启动后切换到闭环FOC的无扰动策略</td><td><a href="./../algorithm/ALG-05-Sensored-FOC.html">ALG-05</a></td></tr></tbody></table></div><h3 id="alg-18-补偿算法-→-关联映射" tabindex="-1">ALG-18 补偿算法 → 关联映射 <a class="header-anchor" href="#alg-18-补偿算法-→-关联映射" aria-label="Permalink to &quot;ALG-18 补偿算法 → 关联映射&quot;">​</a></h3><div class="kb-table-scroll"><table><thead><tr><th>算法知识点</th><th>关联模块</th><th>关联机制</th><th>引用链接</th></tr></thead><tbody><tr><td>死区补偿深化</td><td>ALG-04 死区补偿</td><td>ALG-04讲原理，ALG-18讲工程深化</td><td><a href="./../algorithm/ALG-04-Deadtime-Compensation.html">ALG-04</a></td></tr><tr><td>抗齿槽转矩</td><td>ALG-14 THD谐波</td><td>齿槽转矩是低频谐波的主要来源</td><td><a href="./../algorithm/ALG-14-THD-Harmonic-Analysis.html">ALG-14</a></td></tr><tr><td>角度延迟补偿</td><td>ALG-06 位置速度观测器</td><td>角度预测是观测器的延伸</td><td><a href="./../algorithm/ALG-06-Position-Speed-Observer.html">ALG-06</a></td></tr><tr><td>转速纹波补偿</td><td>ALG-12 速度环</td><td>纹波补偿改善速度环稳态性能</td><td><a href="./../algorithm/ALG-12-Speed-Loop-Torque-Observer.html">ALG-12</a></td></tr></tbody></table></div><h3 id="alg-19-无差拍-→-关联映射" tabindex="-1">ALG-19 无差拍 → 关联映射 <a class="header-anchor" href="#alg-19-无差拍-→-关联映射" aria-label="Permalink to &quot;ALG-19 无差拍 → 关联映射&quot;">​</a></h3><div class="kb-table-scroll"><table><thead><tr><th>算法知识点</th><th>关联模块</th><th>关联机制</th><th>引用链接</th></tr></thead><tbody><tr><td>无差拍vs PI</td><td>ALG-03 PI电流调节器</td><td>无差拍是PI的替代方案，带宽更高但鲁棒性更弱</td><td><a href="./../algorithm/ALG-03-PI-Current-Regulator.html">ALG-03</a></td></tr><tr><td>与MPC的关系</td><td>CT-19 MPC</td><td>无差拍是MPC的特例（代价函数仅含跟踪误差）</td><td><a href="./../control-theory/CT-19-Model-Predictive-Control.html">CT-19</a></td></tr><tr><td>一拍延迟补偿</td><td>ALG-18 角度延迟补偿</td><td>电流预测+角度预测联合补偿</td><td><a href="./../algorithm/ALG-18-Compensation-Algorithms.html">ALG-18</a></td></tr></tbody></table></div><h3 id="ct-19-mpc-→-关联映射" tabindex="-1">CT-19 MPC → 关联映射 <a class="header-anchor" href="#ct-19-mpc-→-关联映射" aria-label="Permalink to &quot;CT-19 MPC → 关联映射&quot;">​</a></h3><div class="kb-table-scroll"><table><thead><tr><th>控制理论知识点</th><th>影响的算法模块</th><th>影响机制</th><th>引用链接</th></tr></thead><tbody><tr><td>FCS-MPC代价函数</td><td>ALG-03 PI电流调节器</td><td>MPC是PI的替代方案，带宽更高但计算量更大</td><td><a href="./../algorithm/ALG-03-PI-Current-Regulator.html">ALG-03</a></td></tr><tr><td>MPC-TC</td><td>ALG-01 FOC理论</td><td>MPC-TC类似DTC但有预测优化</td><td><a href="./../algorithm/ALG-01-FOC-Theory.html">ALG-01</a></td></tr><tr><td>模型参数敏感性</td><td>CT-04 PID控制</td><td>MPC对模型精度要求远高于PI</td><td><a href="./../control-theory/CT-04-PID-Control-Principles.html">CT-04</a></td></tr></tbody></table></div><h3 id="pmi-01-03-→-关联映射" tabindex="-1">PMI-01~03 → 关联映射 <a class="header-anchor" href="#pmi-01-03-→-关联映射" aria-label="Permalink to &quot;PMI-01~03 → 关联映射&quot;">​</a></h3><div class="kb-table-scroll"><table><thead><tr><th>PFC知识点</th><th>关联模块</th><th>关联机制</th><th>引用链接</th></tr></thead><tbody><tr><td>PFC Boost拓扑</td><td>PP-04 PFC</td><td>PMI讲PFC+电机集成，PP-04讲PFC本身</td><td><a href="./../power-path/PP-04-PFC-Power-Factor-Correction.html">PP-04</a></td></tr><tr><td>母线电容设计</td><td>HW-06 电源管理</td><td>PFC纹波+逆变器纹波的矢量叠加</td><td><a href="./../hardware/HW-06-Power-Management-Protection.html">HW-06</a></td></tr><tr><td>AFE有源前端</td><td>ALG-13 保护优化</td><td>制动能量回馈→母线泵升→保护策略</td><td><a href="./../algorithm/ALG-13-Protection-Optimization.html">ALG-13</a></td></tr></tbody></table></div><h3 id="com-08-autosar-→-关联映射" tabindex="-1">COM-08 AUTOSAR → 关联映射 <a class="header-anchor" href="#com-08-autosar-→-关联映射" aria-label="Permalink to &quot;COM-08 AUTOSAR → 关联映射&quot;">​</a></h3><div class="kb-table-scroll"><table><thead><tr><th>AUTOSAR知识点</th><th>关联模块</th><th>关联机制</th><th>引用链接</th></tr></thead><tbody><tr><td>MCAL PWM配置</td><td>HW-04 MCU外设</td><td>AUTOSAR MCAL是对MCU外设的标准化抽象</td><td><a href="./../hardware/HW-04-MCU-Peripherals.html">HW-04</a></td></tr><tr><td>COM通信栈</td><td>COM-01 CAN基础</td><td>AUTOSAR CanIf/PduR是对CAN协议的标准化封装</td><td><a href="./../communication/COM-01-CAN-Basics.html">COM-01</a></td></tr><tr><td>功能安全ASIL</td><td>HW-06 电源保护</td><td>ASIL-D要求冗余电流采样和监控</td><td><a href="./../hardware/HW-06-Power-Management-Protection.html">HW-06</a></td></tr></tbody></table></div><h3 id="com-09-phy-→-关联映射" tabindex="-1">COM-09 PHY → 关联映射 <a class="header-anchor" href="#com-09-phy-→-关联映射" aria-label="Permalink to &quot;COM-09 PHY → 关联映射&quot;">​</a></h3><div class="kb-table-scroll"><table><thead><tr><th>PHY知识点</th><th>关联模块</th><th>关联机制</th><th>引用链接</th></tr></thead><tbody><tr><td>CAN收发器</td><td>COM-01 CAN基础</td><td>PHY是CAN协议的物理基础</td><td><a href="./../communication/COM-01-CAN-Basics.html">COM-01</a></td></tr><tr><td>EtherCAT ESC</td><td>COM-06 EtherCAT</td><td>ESC是EtherCAT协议的硬件实现</td><td><a href="./../communication/COM-06-EtherCAT.html">COM-06</a></td></tr><tr><td>隔离技术</td><td>HW-07 热设计EMC</td><td>隔离是EMC设计的重要组成部分</td><td><a href="./../hardware/HW-07-Thermal-EMC-Design.html">HW-07</a></td></tr></tbody></table></div><h3 id="alg-20-控制视角下方程用途-→-关联映射" tabindex="-1">ALG-20 控制视角下方程用途 → 关联映射 <a class="header-anchor" href="#alg-20-控制视角下方程用途-→-关联映射" aria-label="Permalink to &quot;ALG-20 控制视角下方程用途 → 关联映射&quot;">​</a></h3><div class="kb-table-scroll"><table><thead><tr><th>算法知识点</th><th>关联模块</th><th>关联机制</th><th>引用链接</th></tr></thead><tbody><tr><td>电压方程</td><td>ALG-03 PI电流调节器</td><td>电压方程是PI参数计算的物理基础</td><td><a href="./../algorithm/ALG-03-PI-Current-Regulator.html">ALG-03</a></td></tr><tr><td>磁链方程</td><td>ALG-01 FOC理论</td><td>磁链方程定义了dq轴解耦的数学基础</td><td><a href="./../algorithm/ALG-01-FOC-Theory.html">ALG-01</a></td></tr><tr><td>转矩方程</td><td>HW-01 电机本体</td><td>转矩方程连接了电机参数与控制性能</td><td><a href="./../hardware/HW-01-Motor-Basics.html">HW-01</a></td></tr></tbody></table></div><h3 id="alg-21-参数辨识-→-关联映射" tabindex="-1">ALG-21 参数辨识 → 关联映射 <a class="header-anchor" href="#alg-21-参数辨识-→-关联映射" aria-label="Permalink to &quot;ALG-21 参数辨识 → 关联映射&quot;">​</a></h3><div class="kb-table-scroll"><table><thead><tr><th>算法知识点</th><th>关联模块</th><th>关联机制</th><th>引用链接</th></tr></thead><tbody><tr><td>电阻辨识</td><td>ALG-03 PI电流调节器</td><td>R影响PI比例增益Kp的计算</td><td><a href="./../algorithm/ALG-03-PI-Current-Regulator.html">ALG-03</a></td></tr><tr><td>电感辨识</td><td>ALG-03 PI电流调节器</td><td>L影响PI积分时间常数Ti的计算</td><td><a href="./../algorithm/ALG-03-PI-Current-Regulator.html">ALG-03</a></td></tr><tr><td>磁链辨识</td><td>ALG-07 无感观测器</td><td>磁链参数是反EMF观测器的核心输入</td><td><a href="./../algorithm/ALG-07-Sensorless-Observers.html">ALG-07</a></td></tr><tr><td>惯量辨识</td><td>ALG-12 速度环</td><td>J影响速度环PI参数设计</td><td><a href="./../algorithm/ALG-12-Speed-Loop-Torque-Observer.html">ALG-12</a></td></tr><tr><td>离线检测</td><td>SDK-03 HPM-MC检测</td><td>HPM-MC的离线参数检测是辨识的工程实现</td><td><a href="./../algorithm/HPM-MC/SDK-03-HPM-MC-v2-Detect.html">SDK-03</a></td></tr></tbody></table></div><h3 id="新增文档交叉引用密度统计" tabindex="-1">新增文档交叉引用密度统计 <a class="header-anchor" href="#新增文档交叉引用密度统计" aria-label="Permalink to &quot;新增文档交叉引用密度统计&quot;">​</a></h3><div class="kb-table-scroll"><table><thead><tr><th>模块</th><th>关联数量</th><th>达标(≥2)</th></tr></thead><tbody><tr><td>HW-02B</td><td>3</td><td>✅</td></tr><tr><td>ALG-17</td><td>3</td><td>✅</td></tr><tr><td>ALG-18</td><td>4</td><td>✅</td></tr><tr><td>ALG-19</td><td>3</td><td>✅</td></tr><tr><td>CT-19</td><td>3</td><td>✅</td></tr><tr><td>PMI-01</td><td>1+2(PMI-02/03)</td><td>✅</td></tr><tr><td>PMI-02</td><td>2</td><td>✅</td></tr><tr><td>PMI-03</td><td>2</td><td>✅</td></tr><tr><td>COM-08</td><td>3</td><td>✅</td></tr><tr><td>COM-09</td><td>3</td><td>✅</td></tr><tr><td>ALG-20</td><td>3</td><td>✅</td></tr><tr><td>ALG-21</td><td>5</td><td>✅</td></tr></tbody></table></div>',25)])])}const b=d(h,[["render",l]]);export{c as __pageData,b as default};
